import React, { useState, useEffect, useRef } from 'react';
import Blobs  from '../components/Blobs';
import Orb3D  from '../components/Orb3D';

const PHASES = [
  { name:'Andas in',  seconds:4, colors:['#4060c0','#1a2880','#6080e0'], speed:0.15 },
  { name:'Håll',      seconds:7, colors:['#806020','#402a00','#c09040'], speed:0.05 },
  { name:'Andas ut',  seconds:8, colors:['#306040','#102818','#50a070'], speed:0.2  },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    const p = PHASES[pi];
    setPhase(pi); setCycle(ci); setCount(p.seconds);
    let c = p.seconds;
    timer.current = setInterval(() => {
      c--;
      setCount(c);
      if (c <= 0) {
        clearInterval(timer.current);
        const np = (pi+1) % PHASES.length;
        const nc = np===0 ? ci+1 : ci;
        setTimeout(() => runPhase(np, nc), 300);
      }
    }, 1000);
  };

  const start = () => { setRunning(true); setDone(false); runPhase(0, 0); };
  useEffect(() => () => clearInterval(timer.current), []);

  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 24px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:32 }}>
          <Orb3D size={180} colors={['#306040','#102818','#50a070']} speed={0.15} />
        </div>
        <h2 style={{ fontSize:'clamp(28px,6vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#fff', marginBottom:14 }}>Bra jobbat</h2>
        <p style={{ fontSize:15, color:'rgba(255,255,255,0.4)', marginBottom:40, fontWeight:300 }}>Ditt nervsystem har lugnat ner sig.</p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#0a0a0f', fontSize:13, fontWeight:600 }}>Checka in humöret</button>
          <button onClick={()=>{setDone(false);setRunning(false);}} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(255,255,255,0.6)', fontSize:13 }}>Gör om</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'80px 24px 60px', maxWidth:400, width:'100%', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:14 }}>Andningsövning</p>
        <h1 style={{ fontSize:'clamp(28px,6vw,42px)', fontWeight:700, letterSpacing:'-0.04em', color:'#fff', marginBottom:6, lineHeight:1 }}>4 – 7 – 8</h1>
        <p style={{ fontSize:13, color:'rgba(255,255,255,0.35)', marginBottom:48, fontWeight:300 }}>Aktiverar det parasympatiska nervsystemet.</p>

        {/* Phase steps */}
        {!running && (
          <div style={{ display:'flex', gap:24, justifyContent:'center', marginBottom:48 }}>
            {PHASES.map((p,i)=>(
              <div key={i} style={{ textAlign:'center' }}>
                <div style={{ width:40, height:40, borderRadius:12, background:'rgba(255,255,255,0.06)', border:'1px solid rgba(255,255,255,0.08)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:18, fontWeight:700, color:'#fff', margin:'0 auto 6px' }}>{p.seconds}</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.3)', letterSpacing:'0.1em', textTransform:'uppercase' }}>{p.name}</div>
              </div>
            ))}
          </div>
        )}

        {/* The Orb IS the breathing indicator — expands/contracts */}
        <div style={{ display:'flex', justifyContent:'center', marginBottom:40, position:'relative' }}>
          <div style={{ transition:'transform 0.5s ease', transform: running ? (phase===0?'scale(1.18)':phase===1?'scale(1.18)':'scale(0.88)') : 'scale(1)' }}>
            <Orb3D
              size={200}
              colors={running ? cur.colors : ['#505080','#202040','#7070b0']}
              speed={running ? cur.speed : 0.3}
            />
          </div>

          {/* Count overlay */}
          {running && (
            <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(255,255,255,0.5)', marginBottom:4 }}>{cur.name}</div>
              <div style={{ fontSize:48, fontWeight:700, color:'#fff', lineHeight:1 }}>{count}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.3)', marginTop:8 }}>Omgång {cycle+1} / {TOTAL}</div>
            </div>
          )}
        </div>

        {!running && (
          <button onClick={start} style={{ padding:'15px 48px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#0a0a0f', fontSize:14, fontWeight:600, transition:'opacity .2s' }}
            onMouseEnter={e=>e.currentTarget.style.opacity='.8'} onMouseLeave={e=>e.currentTarget.style.opacity='1'}>
            Starta
          </button>
        )}
      </div>
    </div>
  );
}
